        sourceMode: "error",
        featureCount: 0,
        geometrySummary: {},
        criticalCount: 1,
        warningCount: 0,
        recommendation:
          "Μην ανοίξεις πρόσβαση μέχρι να διορθωθεί το σφάλμα ανάγνωσης του δικτύου.",
        findings: [
          {
            level: "critical",
            title: "Σφάλμα ανάγνωσης δικτύου",
            detail: error instanceof Error ? error.message : "Άγνωστο σφάλμα.",
